#!/usr/bin/env python3
"""Download matched audio + Praat TextGrid pairs from the UCLA voice quality project.

Source: https://www.phonetics.ucla.edu/voiceproject/voice.html

Site structure (verified by inspection, not assumed):
  * Every link is present directly in the static HTML -- nothing is generated by
    JavaScript -- so plain HTML parsing is sufficient. No requests/BeautifulSoup
    needed; this script is stdlib-only.
  * The page does NOT link individual .wav / .TextGrid files. Each language is
    published as a pair of ZIP archives, e.g.
        Gujarati/Gujarati_Audio.zip  +  Gujarati/Gujarati_TextGrids.zip
  * Inside an archive, audio and TextGrids live under different top-level
    folders and are nested in per-speaker subfolders, so pairing is done on the
    file *stem* (basename without extension), which the project keeps identical
    between the two archives.
  * Extension case is inconsistent across languages (.TextGrid vs .textgrid);
    matching is case-insensitive, but original filenames are preserved on disk.

Pairing rules
  1. Archives are grouped per directory by a normalised key (the name with the
     ``audio`` / ``textgrid`` / ``egg`` marker tokens removed). A group is only
     processed if it has BOTH an audio archive and a TextGrid archive.
  2. The TextGrid archive is fetched first. If it is missing or broken, the
     (potentially huge) audio archive is never downloaded.
  3. After extraction, only stems present in BOTH archives are written to disk.
     Audio without a TextGrid is discarded.

Deliberately skipped
  * ``*_EGG.zip`` -- electroglottograph archives also contain .wav files with the
    same stems as the audio, so they would masquerade as audio and clobber the
    real recordings. Use --include-egg only if you know you want them.
  * Audio-only releases such as English_LRRH (1.3 GB, no TextGrids published).

Usage
    python test/download_ucla_voice_data.py --dry-run      # plan + sizes only
    python test/download_ucla_voice_data.py                # download everything
    python test/download_ucla_voice_data.py --only zapotec --only english

Requirements: Python 3.8+. Standard library only.

Note on size: a full run downloads roughly 1.2 GB of archives. They are staged
in a temporary directory and deleted afterwards (use --keep-archives to keep
them, or --work-dir to control where they are staged).
"""

from __future__ import annotations

import argparse
import os
import posixpath
import re
import shutil
import sys
import tempfile
import time
import zipfile
from dataclasses import dataclass, field
from html.parser import HTMLParser
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Set, Tuple
from urllib.error import HTTPError, URLError
from urllib.parse import unquote, urldefrag, urljoin, urlparse
from urllib.request import Request, urlopen

ROOT_URL = "https://www.phonetics.ucla.edu/voiceproject/voice.html"

AUDIO_EXTS = {".wav", ".aiff", ".aif", ".mp3", ".flac", ".ogg", ".au", ".aifc"}
TEXTGRID_EXTS = {".textgrid"}
ARCHIVE_EXTS = {".zip"}
PAGE_EXTS = {".html", ".htm", ""}

USER_AGENT = "vspy-voiceproject-fetcher/1.0 (+research use; stdlib urllib)"

# Marker tokens used to classify and to normalise archive names into group keys.
TEXTGRID_TOKENS = {"textgrid", "textgrids"}
AUDIO_TOKENS = {"audio"}
EGG_TOKENS = {"egg"}


# --------------------------------------------------------------------------- #
# HTTP helpers
# --------------------------------------------------------------------------- #


class Reporter:
    """Collects per-item outcomes so the run can end with a concise summary."""

    def __init__(self) -> None:
        self.downloaded: List[str] = []
        self.overwritten: List[str] = []
        self.skipped: List[Tuple[str, str]] = []
        self.failed: List[Tuple[str, str]] = []

    def skip(self, item: str, reason: str) -> None:
        self.skipped.append((item, reason))

    def fail(self, item: str, reason: str) -> None:
        self.failed.append((item, reason))
        print(f"  ! FAILED {item}: {reason}", file=sys.stderr)


def _request(url: str, method: str = "GET") -> Request:
    return Request(url, headers={"User-Agent": USER_AGENT}, method=method)


def _open(url: str, timeout: float, method: str = "GET"):
    """Open a URL, raising on any non-2xx status.

    urllib follows redirects and raises HTTPError for >=400 on its own; the
    explicit status check guards against unusual 1xx/3xx responses leaking
    through as if they were a successful body.
    """
    response = urlopen(_request(url, method), timeout=timeout)
    status = getattr(response, "status", None) or response.getcode()
    if not (200 <= int(status) < 300):
        response.close()
        raise URLError(f"unexpected HTTP status {status}")
    return response


def _retry(func, retries: int, label: str, timeout: float):
    """Run ``func`` with simple backoff. Returns (result, error_message)."""
    delay = 1.0
    last = ""
    for attempt in range(1, retries + 1):
        try:
            return func(), None
        except HTTPError as exc:
            last = f"HTTP {exc.code} {exc.reason}"
            # 4xx (other than 429) will not fix themselves -- fail fast.
            if 400 <= exc.code < 500 and exc.code != 429:
                break
        except (URLError, TimeoutError, OSError, ValueError) as exc:
            last = f"{type(exc).__name__}: {exc}"
        if attempt < retries:
            print(f"    retry {attempt}/{retries - 1} for {label} ({last})")
            time.sleep(delay)
            delay *= 2
    return None, last


def fetch_text(url: str, timeout: float, retries: int) -> Optional[str]:
    def do() -> str:
        with _open(url, timeout) as response:
            charset = response.headers.get_content_charset() or "utf-8"
            return response.read().decode(charset, errors="replace")

    text, error = _retry(do, retries, url, timeout)
    if error:
        print(f"  ! could not read {url}: {error}", file=sys.stderr)
    return text


def remote_size(url: str, timeout: float) -> Optional[int]:
    """Content-Length via HEAD, or None if the server does not report one."""
    try:
        with _open(url, timeout, method="HEAD") as response:
            length = response.headers.get("Content-Length")
            return int(length) if length is not None else None
    except (HTTPError, URLError, TimeoutError, OSError, ValueError):
        return None


def download_file(url: str, dest: Path, timeout: float, retries: int) -> Tuple[bool, str]:
    """Stream ``url`` to ``dest``. Returns (ok, error_message)."""
    dest.parent.mkdir(parents=True, exist_ok=True)

    # Live progress only makes sense on a terminal; when piped to a file or a
    # log, emit a single line once the transfer is done instead.
    interactive = sys.stdout.isatty()

    def do() -> bool:
        tmp = dest.with_name(dest.name + ".part")
        try:
            with _open(url, timeout) as response, open(tmp, "wb") as handle:
                total = response.headers.get("Content-Length")
                total = int(total) if total and total.isdigit() else 0
                done = 0
                next_mark = 10
                while True:
                    chunk = response.read(1 << 16)
                    if not chunk:
                        break
                    handle.write(chunk)
                    done += len(chunk)
                    if total and interactive:
                        pct = done * 100 // total
                        if pct >= next_mark:
                            print(f"    {pct}% of {total / 1e6:.1f} MB",
                                  end="\r", flush=True)
                            next_mark = pct + 10
            if total and interactive:
                print(" " * 40, end="\r", flush=True)
            print(f"    {done / 1e6:.1f} MB")
            os.replace(tmp, dest)
            return True
        except BaseException:
            tmp.unlink(missing_ok=True)
            raise

    ok, error = _retry(do, retries, url, timeout)
    return bool(ok), error or ""


# --------------------------------------------------------------------------- #
# Crawling
# --------------------------------------------------------------------------- #


class LinkExtractor(HTMLParser):
    """Pulls href/src values out of a static HTML page."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.links: List[str] = []

    def handle_starttag(self, tag: str, attrs) -> None:
        for name, value in attrs:
            if name in ("href", "src") and value:
                self.links.append(value.strip())


def url_ext(url: str) -> str:
    """Lowercased extension of a URL path, percent-decoding first."""
    path = unquote(urlparse(url).path)
    return posixpath.splitext(path)[1].lower()


def url_name(url: str) -> str:
    """Final path segment of a URL, percent-decoded (the original filename)."""
    return posixpath.basename(unquote(urlparse(url).path))


def crawl(root_url: str, timeout: float, retries: int, max_pages: int,
          reporter: Reporter) -> Dict[str, str]:
    """Breadth-first crawl of the project pages. Returns {asset_url: found_on}.

    Restricted to the same host and to the root page's directory, so the crawl
    cannot wander into the rest of the UCLA phonetics site.
    """
    root = urlparse(root_url)
    scope = posixpath.dirname(root.path) + "/"

    def in_scope(url: str) -> bool:
        parts = urlparse(url)
        return (
            parts.scheme in ("http", "https")
            and parts.netloc == root.netloc
            and parts.path.startswith(scope)
        )

    assets: Dict[str, str] = {}
    seen_pages: Set[str] = set()
    queue: List[str] = [root_url]

    while queue and len(seen_pages) < max_pages:
        page = queue.pop(0)
        if page in seen_pages:
            continue
        seen_pages.add(page)

        print(f"  crawling {page}")
        html = fetch_text(page, timeout, retries)
        if html is None:
            reporter.fail(page, "page could not be fetched")
            continue

        parser = LinkExtractor()
        try:
            parser.feed(html)
        except Exception as exc:  # malformed markup should not kill the run
            reporter.fail(page, f"HTML parse error: {exc}")
            continue

        for raw in parser.links:
            if raw.lower().startswith(("mailto:", "javascript:", "tel:", "#")):
                continue
            # urljoin resolves relative links and leaves absolute ones intact.
            url, _ = urldefrag(urljoin(page, raw))
            if not in_scope(url):
                continue
            ext = url_ext(url)
            if ext in PAGE_EXTS:
                if url not in seen_pages:
                    queue.append(url)
            elif ext in ARCHIVE_EXTS | AUDIO_EXTS | TEXTGRID_EXTS:
                assets.setdefault(url, page)

    return assets


# --------------------------------------------------------------------------- #
# Pairing
# --------------------------------------------------------------------------- #


def tokens(name: str) -> List[str]:
    return [t for t in re.split(r"[^A-Za-z0-9]+", name.lower()) if t]


def classify_archive(url: str) -> str:
    """One of: 'textgrid', 'audio', 'egg', 'unknown'."""
    parts = set(tokens(posixpath.splitext(url_name(url))[0]))
    if parts & TEXTGRID_TOKENS:
        return "textgrid"
    if parts & EGG_TOKENS:
        return "egg"
    if parts & AUDIO_TOKENS:
        return "audio"
    return "unknown"


def group_key(url: str) -> str:
    """Directory + name with audio/textgrid/egg markers stripped.

    ``Gujarati/Gujarati_Audio.zip`` and ``Gujarati/Gujarati_TextGrids.zip`` both
    reduce to ``gujarati/gujarati``, which is what makes them a pair.
    """
    path = unquote(urlparse(url).path)
    directory = posixpath.dirname(path).rsplit("/", 1)[-1].lower()
    stem = posixpath.splitext(posixpath.basename(path))[0]
    markers = TEXTGRID_TOKENS | AUDIO_TOKENS | EGG_TOKENS
    kept = [t for t in tokens(stem) if t not in markers]
    return f"{directory}/{'_'.join(kept)}"


@dataclass
class ArchivePair:
    key: str
    audio_url: str
    textgrid_url: str


@dataclass
class FilePair:
    stem: str
    audio_url: str
    textgrid_url: str


def build_plan(assets: Dict[str, str], include_egg: bool,
               reporter: Reporter) -> Tuple[List[ArchivePair], List[FilePair]]:
    """Turn discovered asset URLs into audio/TextGrid pairs."""
    groups: Dict[str, Dict[str, List[str]]] = {}
    direct_audio: Dict[str, str] = {}
    direct_textgrid: Dict[str, str] = {}

    for url in sorted(assets):
        ext = url_ext(url)
        if ext in ARCHIVE_EXTS:
            kind = classify_archive(url)
            if kind == "egg" and not include_egg:
                reporter.skip(url_name(url), "EGG archive (not speech audio)")
                continue
            if kind == "egg":
                kind = "audio"
            if kind == "unknown":
                # Could be anything; without an audio/TextGrid marker there is
                # no partner to pair it with, so leave it alone.
                reporter.skip(url_name(url), "archive is not marked audio or TextGrid")
                continue
            groups.setdefault(group_key(url), {}).setdefault(kind, []).append(url)
        elif ext in AUDIO_EXTS:
            direct_audio[posixpath.splitext(url_name(url))[0]] = url
        elif ext in TEXTGRID_EXTS:
            direct_textgrid[posixpath.splitext(url_name(url))[0]] = url

    archive_pairs: List[ArchivePair] = []
    for key in sorted(groups):
        kinds = groups[key]
        audio = kinds.get("audio", [])
        textgrid = kinds.get("textgrid", [])
        if audio and textgrid:
            # Multiple archives per side are not expected on this site; if it
            # ever happens, pair them up in sorted order and report the rest.
            for index, (a_url, t_url) in enumerate(zip(sorted(audio), sorted(textgrid))):
                suffix = f"#{index + 1}" if index else ""
                archive_pairs.append(ArchivePair(key + suffix, a_url, t_url))
            for extra in sorted(audio)[len(textgrid):]:
                reporter.skip(url_name(extra), "no matching TextGrid archive")
            for extra in sorted(textgrid)[len(audio):]:
                reporter.skip(url_name(extra), "no matching audio archive")
        else:
            for url in audio:
                reporter.skip(url_name(url), "no TextGrid archive published")
            for url in textgrid:
                reporter.skip(url_name(url), "no audio archive published")

    file_pairs: List[FilePair] = []
    for stem in sorted(direct_audio):
        if stem in direct_textgrid:
            file_pairs.append(FilePair(stem, direct_audio[stem], direct_textgrid[stem]))
        else:
            reporter.skip(url_name(direct_audio[stem]), "no corresponding .TextGrid")
    for stem in sorted(direct_textgrid):
        if stem not in direct_audio:
            reporter.skip(url_name(direct_textgrid[stem]), "no corresponding audio file")

    return archive_pairs, file_pairs


# --------------------------------------------------------------------------- #
# Extraction / writing
# --------------------------------------------------------------------------- #


@dataclass
class Destination:
    audio_dir: Path
    textgrid_dir: Path
    # target path -> the archive member it came from, for collision detection.
    written: Dict[Path, str] = field(default_factory=dict)

    def dir_for(self, ext: str) -> Path:
        return self.textgrid_dir if ext in TEXTGRID_EXTS else self.audio_dir


def is_junk(name: str) -> bool:
    """macOS archive noise: __MACOSX/ forks and ._AppleDouble sidecars."""
    base = posixpath.basename(name)
    return name.startswith("__MACOSX/") or "/__MACOSX/" in name or base.startswith("._")


def index_members(zf: zipfile.ZipFile, wanted_exts: Set[str],
                  label: str, reporter: Reporter) -> Dict[str, zipfile.ZipInfo]:
    """Map stem -> member for the members with a wanted extension."""
    found: Dict[str, zipfile.ZipInfo] = {}
    ambiguous: Set[str] = set()
    for info in zf.infolist():
        if info.is_dir() or is_junk(info.filename):
            continue
        name = posixpath.basename(info.filename)
        stem, ext = posixpath.splitext(name)
        if ext.lower() not in wanted_exts or not stem:
            continue
        if stem in found:
            # Two files share a basename in different subfolders; a flat
            # destination cannot hold both unambiguously.
            ambiguous.add(stem)
            continue
        found[stem] = info
    for stem in sorted(ambiguous):
        found.pop(stem, None)
        reporter.skip(f"{label}:{stem}", "duplicate basename inside archive")
    return found


def extract_member(zf: zipfile.ZipFile, info: zipfile.ZipInfo, dest: Destination,
                   source_label: str, reporter: Reporter) -> None:
    """Write one archive member into the destination, overwriting if present."""
    name = posixpath.basename(info.filename)
    ext = posixpath.splitext(name)[1].lower()
    target = dest.dir_for(ext) / name
    origin = f"{source_label}:{info.filename}"

    previous = dest.written.get(target)
    if previous is not None:
        if previous != origin:
            reporter.skip(name, f"name collides with {previous} (kept first)")
        return

    existed = target.exists()
    target.parent.mkdir(parents=True, exist_ok=True)
    tmp = target.with_name(target.name + ".part")
    try:
        with zf.open(info) as src, open(tmp, "wb") as out:
            shutil.copyfileobj(src, out, 1 << 16)
        os.replace(tmp, target)
    except (OSError, zipfile.BadZipFile, RuntimeError) as exc:
        tmp.unlink(missing_ok=True)
        reporter.fail(name, f"could not extract from {source_label}: {exc}")
        return

    dest.written[target] = origin
    (reporter.overwritten if existed else reporter.downloaded).append(name)


def process_archive_pair(pair: ArchivePair, work_dir: Path, dest: Destination,
                         args: argparse.Namespace, reporter: Reporter) -> None:
    print(f"\n[{pair.key}]")

    # TextGrids first: if they are missing, the audio archive (up to 1.3 GB on
    # this site) is never fetched.
    tg_path = work_dir / url_name(pair.textgrid_url)
    print(f"  TextGrids <- {pair.textgrid_url}")
    ok, error = download_file(pair.textgrid_url, tg_path, args.timeout, args.retries)
    if not ok:
        reporter.fail(url_name(pair.textgrid_url), error)
        reporter.skip(url_name(pair.audio_url), "TextGrid archive unavailable")
        return

    try:
        with zipfile.ZipFile(tg_path) as zf:
            tg_members = index_members(zf, TEXTGRID_EXTS, url_name(pair.textgrid_url),
                                       reporter)
    except (zipfile.BadZipFile, OSError) as exc:
        reporter.fail(url_name(pair.textgrid_url), f"unreadable archive: {exc}")
        reporter.skip(url_name(pair.audio_url), "TextGrid archive unreadable")
        return

    if not tg_members:
        reporter.skip(url_name(pair.audio_url), "TextGrid archive contained no TextGrids")
        return
    print(f"  {len(tg_members)} TextGrids")

    audio_path = work_dir / url_name(pair.audio_url)
    print(f"  audio     <- {pair.audio_url}")
    ok, error = download_file(pair.audio_url, audio_path, args.timeout, args.retries)
    if not ok:
        reporter.fail(url_name(pair.audio_url), error)
        return

    try:
        with zipfile.ZipFile(audio_path) as audio_zf, zipfile.ZipFile(tg_path) as tg_zf:
            audio_members = index_members(audio_zf, AUDIO_EXTS,
                                          url_name(pair.audio_url), reporter)
            matched = sorted(set(audio_members) & set(tg_members))
            print(f"  {len(audio_members)} audio files, {len(matched)} matched pairs")

            for stem in sorted(set(audio_members) - set(tg_members)):
                reporter.skip(f"{stem}{posixpath.splitext(audio_members[stem].filename)[1]}",
                              "no corresponding .TextGrid")

            for stem in matched:
                extract_member(audio_zf, audio_members[stem], dest,
                               url_name(pair.audio_url), reporter)
                extract_member(tg_zf, tg_members[stem], dest,
                               url_name(pair.textgrid_url), reporter)
    except (zipfile.BadZipFile, OSError) as exc:
        reporter.fail(url_name(pair.audio_url), f"unreadable archive: {exc}")
        return
    finally:
        if not args.keep_archives:
            audio_path.unlink(missing_ok=True)
            tg_path.unlink(missing_ok=True)


def process_file_pair(pair: FilePair, dest: Destination, args: argparse.Namespace,
                      reporter: Reporter) -> None:
    """Handle audio/TextGrid published as individual files rather than archives."""
    tg_name = url_name(pair.textgrid_url)
    audio_name = url_name(pair.audio_url)
    tg_target = dest.dir_for(url_ext(pair.textgrid_url)) / tg_name
    audio_target = dest.dir_for(url_ext(pair.audio_url)) / audio_name

    if tg_target in dest.written or audio_target in dest.written:
        reporter.skip(audio_name, "already written in this run")
        return

    tg_existed, audio_existed = tg_target.exists(), audio_target.exists()

    ok, error = download_file(pair.textgrid_url, tg_target, args.timeout, args.retries)
    if not ok:
        reporter.fail(tg_name, error)
        reporter.skip(audio_name, "TextGrid unavailable")
        return

    ok, error = download_file(pair.audio_url, audio_target, args.timeout, args.retries)
    if not ok:
        reporter.fail(audio_name, error)
        return

    dest.written[tg_target] = pair.textgrid_url
    dest.written[audio_target] = pair.audio_url
    (reporter.overwritten if tg_existed else reporter.downloaded).append(tg_name)
    (reporter.overwritten if audio_existed else reporter.downloaded).append(audio_name)


# --------------------------------------------------------------------------- #
# Entry point
# --------------------------------------------------------------------------- #


def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
    here = Path(__file__).resolve().parent
    parser = argparse.ArgumentParser(
        description="Download matched audio + TextGrid pairs from the UCLA voice project.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("--url", default=ROOT_URL, help="start page (default: %(default)s)")
    parser.add_argument("--dest", type=Path, default=here,
                        help="destination root (default: this test folder)")
    parser.add_argument("--audio-subdir", default="wav",
                        help="subfolder for audio, matching the existing layout "
                             "(default: %(default)s)")
    parser.add_argument("--textgrid-subdir", default="textgrid",
                        help="subfolder for TextGrids (default: %(default)s)")
    parser.add_argument("--flat", action="store_true",
                        help="write everything straight into --dest instead of subfolders")
    parser.add_argument("--only", action="append", default=[], metavar="PATTERN",
                        help="case-insensitive substring filter on the pair name; "
                             "repeatable")
    parser.add_argument("--dry-run", action="store_true",
                        help="list the pairs and their download sizes, fetch nothing")
    parser.add_argument("--include-egg", action="store_true",
                        help="also treat *_EGG.zip as audio (off by default: EGG "
                             "archives share stems with the real audio)")
    parser.add_argument("--timeout", type=float, default=60.0,
                        help="per-request timeout in seconds (default: %(default)s)")
    parser.add_argument("--retries", type=int, default=3,
                        help="attempts per request (default: %(default)s)")
    parser.add_argument("--max-pages", type=int, default=25,
                        help="crawl limit (default: %(default)s)")
    parser.add_argument("--work-dir", type=Path, default=None,
                        help="where archives are staged (default: a temp directory)")
    parser.add_argument("--keep-archives", action="store_true",
                        help="keep the downloaded .zip files after extraction")
    parser.add_argument("--clean", action="store_true",
                        help="after a successful download, delete any pre-existing "
                             "audio/TextGrid files in the destination that this run "
                             "did not write, so only the downloaded set remains")
    parser.add_argument("--force", action="store_true",
                        help="allow --clean together with --only (otherwise refused: "
                             "it would delete every dataset except the filtered one)")
    return parser.parse_args(argv)


def prune_stale(dest: Destination, reporter: Reporter, dry_run: bool) -> List[str]:
    """Delete media files in the destination that this run did not write.

    Runs only after downloads succeed, so an interrupted or failed run can never
    leave the destination empty. Only audio/TextGrid extensions are touched, and
    only at the top level of the two destination directories -- never
    recursively, and never any other file type.
    """
    media_exts = AUDIO_EXTS | TEXTGRID_EXTS
    removed: List[str] = []
    for directory in {dest.audio_dir, dest.textgrid_dir}:
        if not directory.is_dir():
            continue
        for path in sorted(directory.iterdir()):
            if not path.is_file() or path.suffix.lower() not in media_exts:
                continue
            if path in dest.written:
                continue
            if dry_run:
                removed.append(path.name)
                continue
            try:
                path.unlink()
                removed.append(path.name)
            except OSError as exc:
                reporter.fail(path.name, f"could not delete: {exc}")
    return removed


def matches_filter(name: str, patterns: List[str]) -> bool:
    return not patterns or any(p.lower() in name.lower() for p in patterns)


def print_summary(reporter: Reporter, dest: Destination, dry_run: bool,
                  removed: Optional[List[str]] = None) -> int:
    print("\n" + "=" * 62)
    print("SUMMARY")
    print("=" * 62)
    if dry_run:
        print("  dry run -- nothing was downloaded")
    else:
        print(f"  downloaded (new):  {len(reporter.downloaded)}")
        print(f"  overwritten:       {len(reporter.overwritten)}")
    print(f"  skipped:           {len(reporter.skipped)}")
    print(f"  failed:            {len(reporter.failed)}")
    if removed is not None:
        label = "would remove" if dry_run else "removed (stale)"
        print(f"  {label + ':':<18} {len(removed)}")

    if reporter.skipped:
        reasons: Dict[str, int] = {}
        for _, reason in reporter.skipped:
            reasons[reason] = reasons.get(reason, 0) + 1
        print("\n  skip reasons:")
        for reason, count in sorted(reasons.items(), key=lambda kv: -kv[1]):
            print(f"    {count:5d}  {reason}")

    if reporter.failed:
        print("\n  failures:")
        for item, reason in reporter.failed:
            print(f"    {item}: {reason}")

    if not dry_run:
        print(f"\n  audio     -> {dest.audio_dir}")
        print(f"  TextGrids -> {dest.textgrid_dir}")

    # Failures alone are not fatal (the point is to survive broken links), but
    # a run that produced nothing at all is worth a non-zero exit code.
    if not dry_run and not reporter.downloaded and not reporter.overwritten:
        return 1
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    args = parse_args(argv)
    reporter = Reporter()

    if args.clean and args.only and not args.force:
        print("Refusing --clean together with --only: that would delete every "
              "dataset except the filtered one.\nRe-run with --force if that is "
              "really what you want.", file=sys.stderr)
        return 2

    dest_root = args.dest.resolve()
    dest = Destination(
        audio_dir=dest_root if args.flat else dest_root / args.audio_subdir,
        textgrid_dir=dest_root if args.flat else dest_root / args.textgrid_subdir,
    )

    print(f"Crawling {args.url}")
    assets = crawl(args.url, args.timeout, args.retries, args.max_pages, reporter)
    print(f"  found {len(assets)} candidate asset links")

    archive_pairs, file_pairs = build_plan(assets, args.include_egg, reporter)

    archive_pairs = [p for p in archive_pairs if matches_filter(p.key, args.only)]
    file_pairs = [p for p in file_pairs if matches_filter(p.stem, args.only)]

    print(f"  {len(archive_pairs)} archive pair(s), {len(file_pairs)} direct file pair(s)")

    if args.dry_run:
        total = 0
        for pair in archive_pairs:
            audio_size = remote_size(pair.audio_url, args.timeout)
            tg_size = remote_size(pair.textgrid_url, args.timeout)
            total += (audio_size or 0) + (tg_size or 0)
            size_text = f"{(audio_size or 0) / 1e6:7.1f} MB" if audio_size else "  size ?"
            print(f"  {size_text}  {pair.key}")
            print(f"             audio: {pair.audio_url}")
            print(f"             grids: {pair.textgrid_url}")
        for pair in file_pairs:
            print(f"        file  {pair.stem}")
        if total:
            print(f"\n  total download: {total / 1e6:.1f} MB")
        return print_summary(reporter, dest, dry_run=True)

    dest.audio_dir.mkdir(parents=True, exist_ok=True)
    dest.textgrid_dir.mkdir(parents=True, exist_ok=True)

    if args.work_dir:
        work_dir = args.work_dir.resolve()
        work_dir.mkdir(parents=True, exist_ok=True)
        staging = None
    else:
        staging = tempfile.TemporaryDirectory(prefix="ucla_voice_")
        work_dir = Path(staging.name)

    try:
        for pair in archive_pairs:
            try:
                process_archive_pair(pair, work_dir, dest, args, reporter)
            except Exception as exc:  # one bad language must not end the run
                reporter.fail(pair.key, f"unexpected error: {type(exc).__name__}: {exc}")
        for pair in file_pairs:
            try:
                process_file_pair(pair, dest, args, reporter)
            except Exception as exc:
                reporter.fail(pair.stem, f"unexpected error: {type(exc).__name__}: {exc}")
    finally:
        if staging is not None:
            staging.cleanup()

    # Pruning happens only after downloads succeed, and only if something was
    # actually written -- a failed run must never empty the destination.
    removed = None
    if args.clean:
        if reporter.downloaded or reporter.overwritten:
            removed = prune_stale(dest, reporter, dry_run=False)
        else:
            print("\n  --clean skipped: this run wrote no files.")

    return print_summary(reporter, dest, dry_run=False, removed=removed)


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        print("\nInterrupted.", file=sys.stderr)
        sys.exit(130)
